command:
$out = '<EXPERIMENT_ROOT>\runs\D-Q02-new-r2-v1'
$loaded = @(Get-Content -LiteralPath "$out\loaded-resources.json" -Raw -Encoding UTF8 | ConvertFrom-Json)
foreach ($resource in $loaded) { if ($resource.path -match 'check_(voice|prose)\.py$') { $resource.use = 'read dependency-related lines; executed on first and revised drafts' } }
$counter = "$out\count_words.py"
$loaded += [pscustomobject]@{path=$counter; use='authored local support script; executed on first and revised drafts'; sha256=(Get-FileHash -LiteralPath $counter -Algorithm SHA256).Hash}
$loaded | ConvertTo-Json -Depth 5 | Set-Content -LiteralPath "$out\loaded-resources.json" -Encoding UTF8
